-- =====================================================================
-- Seed data — 500 synthetic alumni records and demo accounts
-- =====================================================================
-- Run AFTER schema.sql and migrations 001 and 002.
--
-- Everything here is synthetic. Names, emails, phone numbers and
-- LinkedIn URLs are placeholders; no real alumnus is represented.
--
-- The demo accounts below share one PUBLIC password. That is
-- deliberate for a portfolio demo on synthetic data. Before any real
-- record is loaded, delete these accounts and create proper ones.
-- =====================================================================

BEGIN;

-- alumni: 500 rows
ON CONFLICT DO NOTHING;

-- academic_records: 500 rows
ON CONFLICT DO NOTHING;

-- employment: 500 rows
ON CONFLICT DO NOTHING;

-- employment_history: 195 rows
ON CONFLICT DO NOTHING;

-- Demo accounts.
-- Password for all three: IUBDemo2026!
-- Staff sign in with the email; alumni with the Student ID.
ON CONFLICT DO NOTHING;

COMMIT;

-- Check it worked: expect 500 / 500 / 500 / 195 / 3
SELECT
  (SELECT COUNT(*) FROM alumni)             AS alumni,
  (SELECT COUNT(*) FROM academic_records)   AS academic,
  (SELECT COUNT(*) FROM employment)         AS employment,
  (SELECT COUNT(*) FROM employment_history) AS history,
  (SELECT COUNT(*) FROM users)              AS accounts;
